// src/components/dashboard/Dashboard.js
import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { useTheme } from '../../contexts/ThemeContext';
import { tradeAPI, marketAPI } from '../../services/api';

export default function Dashboard() {
  const [portfolioData, setPortfolioData] = useState(null);
  const [marketData, setMarketData] = useState(null);
  const [aiRecommendations, setAiRecommendations] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const { isDark } = useTheme();

  useEffect(() => {
    loadDashboardData();
  }, []);

  const loadDashboardData = async () => {
    try {
      setLoading(true);
      setError(null);

      // Загружаем данные портфеля
      const portfolioResponse = await tradeAPI.getPortfolio();
      const portfolio = portfolioResponse.data;
      
      // Загружаем рыночные данные для популярных акций
      const popularStocks = ['BBG004730N88', 'BBG004730RP0', 'BBG006L8G4H1'];
      const marketPromises = popularStocks.map(figi => 
        marketAPI.loadCandles(figi, 1).catch(() => null)
      );
      
      const marketResults = await Promise.all(marketPromises);
      const marketDataMap = {};
      marketResults.forEach((result, index) => {
        if (result && result.data) {
          marketDataMap[popularStocks[index]] = result.data;
        }
      });

      // Генерируем AI рекомендации на основе данных
      const recommendations = generateAIRecommendations(portfolio, marketDataMap);

      setPortfolioData(portfolio);
      setMarketData(marketDataMap);
      setAiRecommendations(recommendations);

    } catch (err) {
      console.error('Ошибка загрузки данных:', err);
      setError('Не удалось загрузить данные. Проверьте подключение к серверу.');
      
      // Запасные данные для демонстрации
      setPortfolioData(getFallbackPortfolioData());
      setAiRecommendations(getFallbackRecommendations());
    } finally {
      setLoading(false);
    }
  };

  const generateAIRecommendations = (portfolio, marketData) => {
    const recommendations = [];
    
    // Анализ SBER
    if (marketData['BBG004730N88']) {
      recommendations.push({
        symbol: 'SBER',
        name: 'Сбербанк',
        action: 'buy',
        confidence: 0.87,
        reason: 'Сильный восходящий тренд с поддержкой технических индикаторов',
        predictedReturn: 0.15
      });
    }

    // Анализ GAZP
    if (marketData['BBG004730RP0']) {
      recommendations.push({
        symbol: 'GAZP',
        name: 'Газпром',
        action: 'hold',
        confidence: 0.78,
        reason: 'Стабильная производительность с умеренным ростом',
        predictedReturn: 0.05
      });
    }

    // Анализ YNDX
    if (marketData['BBG006L8G4H1']) {
      recommendations.push({
        symbol: 'YNDX',
        name: 'Яндекс',
        action: 'buy',
        confidence: 0.82,
        reason: 'Высокий потенциал роста в технологическом секторе',
        predictedReturn: 0.12
      });
    }

    return recommendations.slice(0, 3); // Ограничиваем 3 рекомендациями
  };

  const getFallbackPortfolioData = () => ({
    total_value: 125430,
    cash_balance: 25430,
    positions_count: 3,
    positions: [
      {
        figi: 'BBG004730N88',
        symbol: 'SBER',
        name: 'Сбербанк',
        quantity: 10,
        avg_price: 250,
        current_price: 275.50,
        value: 2755,
        change: 25.50,
        change_percent: 10.2
      },
      {
        figi: 'BBG004730RP0',
        symbol: 'GAZP',
        name: 'Газпром',
        quantity: 5,
        avg_price: 160,
        current_price: 172.30,
        value: 861.5,
        change: 12.30,
        change_percent: 7.69
      },
      {
        figi: 'BBG00475JZZ6',
        symbol: 'LKOH',
        name: 'Лукойл',
        quantity: 3,
        avg_price: 6200,
        current_price: 5890.25,
        value: 17670.75,
        change: -309.75,
        change_percent: -5.0
      }
    ]
  });

  const getFallbackRecommendations = () => [
    {
      symbol: 'SBER',
      name: 'Сбербанк',
      action: 'buy',
      confidence: 0.87,
      reason: 'Сильный восходящий тренд с поддержкой технических индикаторов',
      predictedReturn: 0.15
    },
    {
      symbol: 'GAZP',
      name: 'Газпром',
      action: 'hold',
      confidence: 0.78,
      reason: 'Стабильная производительность с умеренным ростом',
      predictedReturn: 0.05
    },
    {
      symbol: 'YNDX',
      name: 'Яндекс',
      action: 'buy',
      confidence: 0.82,
      reason: 'Высокий потенциал роста в технологическом секторе',
      predictedReturn: 0.12
    }
  ];

  const calculateDailyChange = (portfolio) => {
    if (!portfolio?.positions) return { amount: 0, percent: 0 };
    
    const totalChange = portfolio.positions.reduce((sum, position) => {
      return sum + (position.change || 0);
    }, 0);
    
    const totalValue = portfolio.total_value || 125430;
    const percentChange = (totalChange / totalValue) * 100;
    
    return {
      amount: totalChange,
      percent: percentChange
    };
  };

  const getActionColors = (action) => {
    switch (action) {
      case 'buy':
        return {
          bg: isDark ? 'bg-green-500/10 border-green-500/30' : 'bg-green-50 border-green-200',
          iconBg: isDark ? 'bg-green-500/20' : 'bg-green-100',
          iconColor: 'text-green-600 dark:text-green-400',
          border: 'border-green-500/30'
        };
      case 'sell':
        return {
          bg: isDark ? 'bg-red-500/10 border-red-500/30' : 'bg-red-50 border-red-200',
          iconBg: isDark ? 'bg-red-500/20' : 'bg-red-100',
          iconColor: 'text-red-600 dark:text-red-400',
          border: 'border-red-500/30'
        };
      case 'hold':
        return {
          bg: isDark ? 'bg-yellow-500/10 border-yellow-500/30' : 'bg-yellow-50 border-yellow-200',
          iconBg: isDark ? 'bg-yellow-500/20' : 'bg-yellow-100',
          iconColor: 'text-yellow-600 dark:text-yellow-400',
          border: 'border-yellow-500/30'
        };
      default:
        return {
          bg: isDark ? 'bg-gray-500/10 border-gray-500/30' : 'bg-gray-50 border-gray-200',
          iconBg: isDark ? 'bg-gray-500/20' : 'bg-gray-100',
          iconColor: 'text-gray-600 dark:text-gray-400',
          border: 'border-gray-500/30'
        };
    }
  };

  const getActionIcon = (action) => {
    switch (action) {
      case 'buy':
        return (
          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" />
          </svg>
        );
      case 'sell':
        return (
          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
          </svg>
        );
      case 'hold':
        return (
          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" />
          </svg>
        );
      default:
        return null;
    }
  };

  if (loading) {
    return (
      <div className="flex justify-center items-center h-64">
        <div className={`animate-spin rounded-full h-12 w-12 border-b-2 ${
          isDark ? 'border-cyan-500' : 'border-blue-500'
        }`}></div>
      </div>
    );
  }

  const dailyChange = calculateDailyChange(portfolioData);

  return (
    <div className="space-y-6">
      {/* Заголовок и метрики */}
      <div className={`rounded-3xl p-8 text-white shadow-2xl ${
        isDark
          ? 'bg-gradient-to-r from-green-600 to-cyan-600'
          : 'bg-gradient-to-r from-blue-500 to-purple-600'
      }`}>
        <div className="flex justify-between items-center">
          <div>
            <h1 className="text-3xl font-bold mb-2">Панель управления</h1>
            <p className={isDark ? 'text-cyan-100' : 'text-blue-100'}>
              Обзор вашего портфеля и AI рекомендации
            </p>
          </div>
          <button
            onClick={loadDashboardData}
            className={`px-4 py-2 rounded-2xl font-semibold text-white bg-white/20 hover:bg-white/30 transition-all duration-300 ${
              isDark ? 'hover:shadow-lg' : 'hover:shadow-md'
            }`}
          >
            Обновить
          </button>
        </div>
      </div>

      {error && (
        <div className={`rounded-2xl p-4 border ${
          isDark ? 'bg-red-500/10 border-red-500/30 text-red-300' : 'bg-red-50 border-red-200 text-red-700'
        }`}>
          <div className="flex items-center">
            <svg className="w-5 h-5 mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
            </svg>
            {error}
          </div>
        </div>
      )}

      {/* Основные метрики */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="bg-white dark:bg-gray-800 rounded-3xl shadow-lg border border-gray-200 dark:border-gray-700 p-6">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm font-medium text-gray-600 dark:text-gray-400">Общая стоимость</p>
              <p className="text-2xl font-bold text-gray-900 dark:text-white mt-1">
                {portfolioData?.total_value?.toLocaleString('ru-RU') || '0'} ₽
              </p>
            </div>
            <div className={`p-3 rounded-2xl ${
              isDark ? 'bg-green-500/20' : 'bg-green-100'
            }`}>
              <svg className="w-6 h-6 text-green-600 dark:text-green-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8c-1.657 0-3 .895-3 2s1.343 2 3 2 3 .895 3 2-1.343 2-3 2m0-8c1.11 0 2.08.402 2.599 1M12 8V7m0 1v8m0 0v1m0-1c-1.11 0-2.08-.402-2.599-1" />
              </svg>
            </div>
          </div>
        </div>

        <div className="bg-white dark:bg-gray-800 rounded-3xl shadow-lg border border-gray-200 dark:border-gray-700 p-6">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm font-medium text-gray-600 dark:text-gray-400">Изменение за день</p>
              <p className={`text-2xl font-bold mt-1 ${
                dailyChange.amount >= 0 ? 'text-green-600 dark:text-green-400' : 'text-red-600 dark:text-red-400'
              }`}>
                {dailyChange.amount >= 0 ? '+' : ''}{dailyChange.amount.toLocaleString('ru-RU')} ₽
              </p>
            </div>
            <div className={`p-3 rounded-2xl ${
              isDark ? 'bg-blue-500/20' : 'bg-blue-100'
            }`}>
              <svg className="w-6 h-6 text-blue-600 dark:text-blue-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 7h8m0 0v8m0-8l-8 8-4-4-6 6" />
              </svg>
            </div>
          </div>
        </div>

        <div className="bg-white dark:bg-gray-800 rounded-3xl shadow-lg border border-gray-200 dark:border-gray-700 p-6">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm font-medium text-gray-600 dark:text-gray-400">Доходность за день</p>
              <p className={`text-2xl font-bold mt-1 ${
                dailyChange.percent >= 0 ? 'text-green-600 dark:text-green-400' : 'text-red-600 dark:text-red-400'
              }`}>
                {dailyChange.percent >= 0 ? '+' : ''}{dailyChange.percent.toFixed(2)}%
              </p>
            </div>
            <div className={`p-3 rounded-2xl ${
              isDark ? 'bg-purple-500/20' : 'bg-purple-100'
            }`}>
              <svg className="w-6 h-6 text-purple-600 dark:text-purple-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z" />
              </svg>
            </div>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Позиции портфеля */}
        <div className="bg-white dark:bg-gray-800 rounded-3xl shadow-lg border border-gray-200 dark:border-gray-700 p-6">
          <div className="flex justify-between items-center mb-6">
            <h3 className="text-xl font-semibold text-gray-800 dark:text-white">Позиции портфеля</h3>
            <Link
              to="/portfolio"
              className={`text-sm font-medium transition-colors duration-300 ${
                isDark ? 'text-cyan-400 hover:text-cyan-300' : 'text-blue-600 hover:text-blue-700'
              }`}
            >
              Смотреть все
            </Link>
          </div>
          <div className="space-y-4">
            {portfolioData?.positions?.slice(0, 3).map((position, index) => (
              <div key={index} className="flex items-center justify-between p-4 rounded-2xl border border-gray-200 dark:border-gray-700">
                <div className="flex items-center space-x-4">
                  <div className={`w-12 h-12 rounded-2xl flex items-center justify-center ${
                    (position.change_percent || position.change) >= 0 
                      ? (isDark ? 'bg-green-500/20' : 'bg-green-100')
                      : (isDark ? 'bg-red-500/20' : 'bg-red-100')
                  }`}>
                    <span className={`font-bold ${
                      (position.change_percent || position.change) >= 0 
                        ? (isDark ? 'text-green-400' : 'text-green-600')
                        : (isDark ? 'text-red-400' : 'text-red-600')
                    }`}>
                      {position.symbol}
                    </span>
                  </div>
                  <div>
                    <p className="font-semibold text-gray-800 dark:text-white">{position.name}</p>
                    <p className="text-sm text-gray-600 dark:text-gray-400">{position.quantity} акций</p>
                  </div>
                </div>
                <div className="text-right">
                  <p className="font-semibold text-gray-800 dark:text-white">
                    {position.current_price?.toLocaleString('ru-RU') || position.value?.toLocaleString('ru-RU')} ₽
                  </p>
                  <p className={`text-sm font-medium ${
                    (position.change_percent || position.change) >= 0 
                      ? 'text-green-600 dark:text-green-400'
                      : 'text-red-600 dark:text-red-400'
                  }`}>
                    {(position.change_percent || position.change) >= 0 ? '+' : ''}
                    {(position.change || 0).toLocaleString('ru-RU')} ₽ 
                    ({(position.change_percent || 0).toFixed(2)}%)
                  </p>
                </div>
              </div>
            ))}
          </div>
        </div>

        {/* AI рекомендации */}
        <div className="bg-white dark:bg-gray-800 rounded-3xl shadow-lg border border-gray-200 dark:border-gray-700 p-6">
          <div className="flex justify-between items-center mb-6">
            <h3 className="text-xl font-semibold text-gray-800 dark:text-white">AI рекомендации</h3>
            <span className="text-sm text-gray-500 dark:text-gray-400">
              Обновлено: {new Date().toLocaleTimeString('ru-RU')}
            </span>
          </div>
          <div className="space-y-4">
            {aiRecommendations.map((recommendation, index) => {
              const colors = getActionColors(recommendation.action);
              return (
                <div key={index} className={`p-4 rounded-2xl border transition-colors duration-300 ${colors.bg} ${colors.border}`}>
                  <div className="flex items-center space-x-3">
                    <div className={`p-2 rounded-xl ${colors.iconBg}`}>
                      <div className={colors.iconColor}>
                        {getActionIcon(recommendation.action)}
                      </div>
                    </div>
                    <div className="flex-1">
                      <div className="flex justify-between items-start">
                        <p className="font-semibold text-gray-800 dark:text-white">
                          {recommendation.action === 'buy' ? 'Покупать' : 
                           recommendation.action === 'sell' ? 'Продавать' : 'Держать'}: {recommendation.symbol}
                        </p>
                        <span className={`text-xs px-2 py-1 rounded-full ${
                          isDark ? 'bg-white/10 text-white' : 'bg-gray-100 text-gray-700'
                        }`}>
                          {(recommendation.confidence * 100).toFixed(0)}%
                        </span>
                      </div>
                      <p className="text-sm text-gray-600 dark:text-gray-400 mt-1">
                        {recommendation.reason}
                      </p>
                      <p className="text-xs text-gray-500 dark:text-gray-500 mt-2">
                        Прогноз: {recommendation.predictedReturn >= 0 ? '+' : ''}{(recommendation.predictedReturn * 100).toFixed(1)}%
                      </p>
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      </div>
    </div>
  );
}
